// The themes SimuLancer, MarkoWizard and PapeRanger share: six classes from the RPG
// icon set, each light and dark (the colors are generated by rpg-icons/temas.py and
// live in the stylesheet). Loaded in <head>, so the saved theme applies before the
// first paint. It sets data-theme (the class) and data-mode (light or dark, resolved
// from "auto" by the system) on <html>, fires "themechange" on document, and offers a
// small picker: THEME.picker(button) opens it under the button.
var THEME_APP = 'markowizard';  // localStorage keys: markowizard.theme, markowizard.mode
var THEME_DEFAULT = 'wizard';  // the app's own class

var THEMES = [
  { id: 'wizard', name: 'Violet Wizard', accent: '#6a2b8f', darkAccent: '#ce79f5', dark: '#110d18' },
  { id: 'dragoon', name: 'Crimson Dragoon', accent: '#c62828', darkAccent: '#ee7b72', dark: '#110d18' },
  { id: 'ranger', name: 'Forest Ranger', accent: '#2e7d32', darkAccent: '#9ccc65', dark: '#09120e' },
  { id: 'paladin', name: 'Cobalt Paladin', accent: '#1565c0', darkAccent: '#42a5f5', dark: '#091018' },
  { id: 'monk', name: 'Amber Monk', accent: '#b54f00', darkAccent: '#ffa726', dark: '#130f09' },
  { id: 'necromancer', name: 'Teal Necromancer', accent: '#047c6f', darkAccent: '#26c6da', dark: '#091115' }
];
var MODES = [{ id: 'auto', name: 'Auto' }, { id: 'light', name: 'Light' }, { id: 'dark', name: 'Dark' }];

var THEME = (function (app, defaultTheme) {
  var KEY = app + '.theme';
  var MODE_KEY = app + '.mode';
  var LIGHT_BG = '#f9f9f7';
  var systemDark = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;

  function find(id) {
    for (var i = 0; i < THEMES.length; i++) {
      if (THEMES[i].id === id) return THEMES[i];
    }
    return null;
  }

  function load(key) {
    try { return localStorage.getItem(key); } catch (e) { return null; /* storage unavailable */ }
  }

  function save(key, value) {
    try { localStorage.setItem(key, value); } catch (e) { /* storage unavailable: just don't remember */ }
  }

  function current() {
    return find(load(KEY)) || find(defaultTheme);
  }

  function mode() {
    var saved = load(MODE_KEY);
    return saved === 'light' || saved === 'dark' ? saved : 'auto';
  }

  function isDark() {
    var m = mode();
    return m === 'dark' || (m === 'auto' && !!systemDark && systemDark.matches);
  }

  function apply() {
    var theme = current();
    var dark = isDark();
    var root = document.documentElement;
    root.setAttribute('data-theme', theme.id);
    root.setAttribute('data-mode', dark ? 'dark' : 'light');
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', dark ? theme.dark : LIGHT_BG);
    var event;
    try { event = new CustomEvent('themechange'); } catch (e) { event = null; }
    if (event) document.dispatchEvent(event);
    return theme;
  }

  if (systemDark && systemDark.addEventListener) {
    systemDark.addEventListener('change', apply);
  }

  // --- the picker ---------------------------------------------------------------

  var open = null;

  function close() {
    if (!open) return;
    open.pop.remove();
    open.button.setAttribute('aria-expanded', 'false');
    document.removeEventListener('mousedown', onOutside, true);
    document.removeEventListener('keydown', onKey, true);
    open = null;
  }

  function onOutside(e) {
    if (open && !open.pop.contains(e.target) && !open.button.contains(e.target)) close();
  }

  function onKey(e) {
    if (e.key === 'Escape') { close(); }
  }

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text) node.textContent = text;
    return node;
  }

  function fill(pop) {
    pop.innerHTML = '';
    pop.appendChild(el('div', 'theme-pop__title', 'Theme'));
    var modes = el('div', 'theme-pop__modes');
    MODES.forEach(function (m) {
      var b = el('button', m.id === mode() ? 'is-active' : '', m.name);
      b.type = 'button';
      b.setAttribute('aria-pressed', m.id === mode() ? 'true' : 'false');
      b.addEventListener('click', function () { save(MODE_KEY, m.id); apply(); fill(pop); });
      modes.appendChild(b);
    });
    pop.appendChild(modes);
    var list = el('div', 'theme-pop__classes');
    var active = current().id;
    var dark = isDark();
    THEMES.forEach(function (t) {
      var b = el('button', t.id === active ? 'is-active' : '');
      b.type = 'button';
      b.setAttribute('aria-pressed', t.id === active ? 'true' : 'false');
      var dot = el('span', 'theme-pop__dot');
      dot.style.background = dark ? t.darkAccent : t.accent;
      b.appendChild(dot);
      b.appendChild(el('span', null, t.name));
      b.addEventListener('click', function () { save(KEY, t.id); apply(); fill(pop); });
      list.appendChild(b);
    });
    pop.appendChild(list);
  }

  function picker(button) {
    if (open) { var same = open.button === button; close(); if (same) return; }
    var pop = el('div', 'theme-pop');
    pop.setAttribute('role', 'dialog');
    pop.setAttribute('aria-label', 'Theme');
    fill(pop);
    document.body.appendChild(pop);
    var r = button.getBoundingClientRect();
    pop.style.top = Math.round(r.bottom + 6) + 'px';
    pop.style.right = Math.max(8, Math.round(document.documentElement.clientWidth - r.right)) + 'px';
    button.setAttribute('aria-expanded', 'true');
    open = { pop: pop, button: button };
    document.addEventListener('mousedown', onOutside, true);
    document.addEventListener('keydown', onKey, true);
  }

  apply();
  return { current: current, mode: mode, isDark: isDark, apply: apply, picker: picker };
})(THEME_APP, THEME_DEFAULT);
